import{_ as n,l as r,o as e,c as l,v as h,p as i,x as t,d as s,i as c,S as C}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"ChaCha20","description":"","frontmatter":{"title":"ChaCha20","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/chacha20.md","filePath":"cs/chacha20.md","lastUpdated":1789023840000}'),d={name:"cs/chacha20.md"};function E(p,a,A,S,_,m){const o=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=h('<h1 id="chacha20" tabindex="-1">ChaCha20 <a class="header-anchor" href="#chacha20" aria-label="Permalink to &quot;ChaCha20&quot;">​</a></h1><div class="epigraph"><p>ChaCha 用加、循环移位与异或在软件里造密钥流：没有 S 盒查表，缓存定时更老实。它仍是计算安全的 PRG 式构造，密钥与 nonce 合同与 AES 一样严格。</p><footer>—— Bernstein, ChaCha, a variant of Salsa20；RFC 8439（ChaCha20-Poly1305）</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/feistel-des">Feistel 与 DES</a>说明旧分组密码的结构债。缺口是<strong>软件平台上的流密码</strong>：AES 在无 AES-NI 时易因查表泄漏，ChaCha 用 ARX 躲开这张表。不重写一次一密，也不把「无表」写成完善保密。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>AES 课的 S 盒在软件里常是内存查表，命中模式可当侧信道。<a href="/cs/side-channel">侧信道直觉</a>已警告计时；本课落到候选：ChaCha20 把 256 比特密钥、96 比特 nonce、32 比特计数器扩成密钥流，再与明文异或。Poly1305 在 RFC 8439 里补 MAC。缺口是 ARX 流密码的合同，不是又一个 SPN。</p><h3 id="nonce-仍不能复用" tabindex="-1">nonce 仍不能复用 <a class="header-anchor" href="#nonce-仍不能复用" aria-label="Permalink to &quot;nonce 仍不能复用&quot;">​</a></h3><p>流密码异或与一次一密同形，复用 nonce 则两段明文之差泄漏。ChaCha 不赦免这条。</p><p><span class="marginnote">Bernstein 的 Salsa20/ChaCha。TLS 1.3 与许多移动实现选 ChaCha20-Poly1305 当 AES-GCM 的软件备胎。本课不写利用缓存的测量步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>描述状态矩阵：常数、密钥、计数、nonce。四分之一圈的 ARX。计数器模式式的块编号给出可寻址密钥流。对照 AES-CTR：同是 PRG 用法，置换族不同。</p>',12)),(e(),i(C,null,{default:t(()=>[c(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20ST%5B%22%E7%8A%B6%E6%80%81%3A%20%E5%AF%86%E9%92%A5%20nonce%20%E8%AE%A1%E6%95%B0%22%5D%20--%3E%20ARX%5B%22ARX%20%E5%9B%9B%E5%88%86%E4%B9%8B%E4%B8%80%E5%9C%88%22%5D%0A%20%20%20%20ARX%20--%3E%20KS%5B%22%E5%AF%86%E9%92%A5%E6%B5%81%E5%9D%97%22%5D%0A%20%20%20%20KS%20--%3E%20XOR%5B%22%E4%B8%8E%E6%98%8E%E6%96%87%E5%BC%82%E6%88%96%22%5D%0A%20%20%20%20XOR%20--%3E%20CT%5B%22%E5%AF%86%E6%96%87%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=h('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>作为 PRG，ChaCha 把短密钥拉成密钥流；完整性要另配 Poly1305 或走 AEAD 包装。它不替代公钥，不替代证书。CPU 有 AES-NI 时 AES-GCM 常更快；无硬件时 ChaCha 更可预测。二者都是计算安全候选。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Salsa 族全部变体列成菜单。AEAD 如何把保密与认证收成一次调用，下一课进 GCM 内部——ChaCha-Poly 是平行实例，机制课以 GCM 为解剖对象。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DES 对照之后，软件向密钥流选 ARX。</li><li>ChaCha20：无 S 盒表，计数器编址密钥流。</li><li>复用 nonce 与一次一密复用密钥同类失败。</li><li>下一课解剖 AEAD，以 GCM 为内部。</li><li>出处：Bernstein, ChaCha；RFC 8439；对照 Salsa20。</li></ul>',8))])}const P=n(d,[["render",E]]);export{f as __pageData,P as default};
